#!/usr/bin/env bash
# The terminal UI in a real tmux pane, against a throwaway root: move entries
# to a new category, save, then check the screen, the generated file and both
# backups. Skipped with a message when bun is not installed.
set -euo pipefail
cd "$(dirname "$0")/../.."
root=$PWD
if ! command -v bun >/dev/null 2>&1; then
  echo "tui smoke: bun is not installed, skipping (https://bun.sh)"
  exit 0
fi
(cd tui && bun install --frozen-lockfile >/dev/null)
source tests/smoke/lib.sh
tmp=$(mktemp -d)
cfg="$tmp/cfg"
mkdir -p "$cfg/lua"
cp tests/fixtures/user_mappings.lua "$cfg/lua/mappings.lua"
env_xdg=(env XDG_CONFIG_HOME="$tmp/c" XDG_DATA_HOME="$tmp/d" XDG_STATE_HOME="$tmp/s" XDG_CACHE_HOME="$tmp/x")
trap 'smoke_stop; smoke_rmdir "$tmp"' EXIT
fail=0
chk() { "$@" || fail=1; }

# No template yet: the UI offers the import.
smoke_start 120 36 "${env_xdg[@]}" bun tui/src/index.tsx --root "$cfg"
sleep 2
chk smoke_expect 'There is no keymap template yet'
chk smoke_expect 'import it, every entry starts as Uncategorized'
smoke_keys y
sleep 1
chk smoke_expect '! Uncategorized +[0-9]+'
chk smoke_expect 'imported [0-9]+ maps and [0-9]+ raw blocks'
chk smoke_expect 'Categories'
chk smoke_expect 'Details'
chk smoke_expect 'move to\.\.\.'
chk smoke_reject 'unsaved|changes'

# Mark two entries, move them to a new category.
smoke_keys l
smoke_keys Space
smoke_keys Space
smoke_keys m
chk smoke_expect 'move 2 entries to'
smoke_type 'Smoke test'
chk smoke_expect '\+ new category "Smoke test"'
smoke_keys Enter
chk smoke_expect 'moved 2 entries to the new category "Smoke test"'
chk smoke_expect '■ Smoke test +2'
chk smoke_expect '3 changes'

# Quitting with unsaved changes asks; n stays.
smoke_type q
chk smoke_expect 'unsaved changes'
chk smoke_expect 'discard and quit'
smoke_type n
chk smoke_reject 'discard and quit'

# Save: summary, confirm, result with both backups.
smoke_type w
chk smoke_expect 'moved 2 entries'
chk smoke_expect 'new 1 category: Smoke test'
chk smoke_expect 'hand-written'
if grep -q AUTOGENERATED "$cfg/lua/mappings.lua"; then
  echo "  FAIL  nothing may be written before the confirm"
  fail=1
fi
smoke_type y
sleep 1
chk smoke_expect 'template saved'
chk smoke_expect 'backup: lua/mappings\.template_[0-9_:]+\.bak'
chk smoke_expect 'wrote lua/mappings\.lua'
chk smoke_expect 'backup: lua/mappings_[0-9_:]+\.bak'
smoke_type x
chk smoke_expect 'saved'
chk smoke_reject 'changes'

# The files.
head -1 "$cfg/lua/mappings.lua" | grep -q '^-- AUTOGENERATED by keymap-helper' || { echo "  FAIL  header missing"; fail=1; }
grep -q '│ Smoke test' "$cfg/lua/mappings.lua" && echo "  ok    category header in the generated file" || { echo "  FAIL  no Smoke test header"; fail=1; }
grep -q '"title": "Smoke test"' "$cfg/lua/mappings.template.json" && echo "  ok    category in the template" || { echo "  FAIL  template lacks the category"; fail=1; }
n_map=$(find "$cfg/lua" -name 'mappings_*.bak' | wc -l)
n_tpl=$(find "$cfg/lua" -name 'mappings.template_*.bak' | wc -l)
[ "$n_map" -eq 1 ] && echo "  ok    one mappings backup" || { echo "  FAIL  mappings backups: $n_map"; fail=1; }
cmp -s "$(find "$cfg/lua" -name 'mappings_*.bak')" tests/fixtures/user_mappings.lua && echo "  ok    the backup is the original file" || { echo "  FAIL  backup differs from the original"; fail=1; }
# the template had no earlier file at the first import, so its backup appears on this save only when one existed
[ "$n_tpl" -eq 1 ] && echo "  ok    one template backup" || { echo "  FAIL  template backups: $n_tpl"; fail=1; }

# Clean quit now.
smoke_type q
sleep 1
tmux -L "$SMOKE_SOCK" list-panes 2>/dev/null | grep -q . && { echo "  FAIL  the UI did not quit"; fail=1; } || echo "  ok    q quit with nothing unsaved"
[ "$fail" -eq 0 ] && echo "tui smoke: ok"
exit "$fail"
